class DetectSquares { unordered_map<int,unordered_map<int,int>> columns;int frequency(int x,int y){return columns[x][y];}public: DetectSquares(){}void add(vector<int> point){++columns[point[0]][point[1]];}int count(vector<int> point){int x=point[0],y=point[1],answer=0;for(auto [otherY,vertical]:columns[x])if(otherY!=y){int side=abs(otherY-y);answer+=vertical*frequency(x+side,y)*frequency(x+side,otherY);answer+=vertical*frequency(x-side,y)*frequency(x-side,otherY);}return answer;} };
